  function ensureSavedActions(){const picker=root.querySelector('.dn-patient-pick');if(item?.id&&picker)picker.remove();if(item?.id&&edit()&&!root.querySelector('[data-dn=delete]')){const el=document.createElement('div');el.className='dn-record-actions';el.innerHTML='<button data-dn="delete" class="dn-danger">이 기록 삭제</button>';el.querySelector('button').onclick=()=>void remove();root.querySelector('[data-dn-body]')?.append(el);}}
