   el.querySelector('[data-editor-close]').onclick=()=>{editorOpen=false;el.classList.remove('dn-editor-open');root.querySelector('[data-tooth="'+selected+'"]')?.focus({preventScroll:true});};el.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>{const ids=D.navigationOrder(item.body.species),i=ids.indexOf(selected),step=Number(e.dataset.step);let next='';for(let n=1;n<ids.length;n++){const id=ids[(i+step*n+ids.length)%ids.length];if(matchesTooth(id)){next=id;break;}}if(!next){notice('이 조건에서 이동할 다른 치아가 없습니다.');return;}selected=next;const imageSelect=root.querySelector('[data-image-tooth]');if(imageSelect)imageSelect.value=selected;refreshChart();renderEditor(true);});
   const set=(k,v)=>{if(!edit()||conflict)return;if(multi){batch[k]=v;if(v===true&&['missing','extracted','extractionPlan'].includes(k))for(const other of ['missing','extracted','extractionPlan'])if(other!==k)batch[other]=false;syncDetails(batch,k,v,true);syncPocket(batch,k);el.querySelectorAll('input[type=checkbox]').forEach(e=>e.checked=!!batch[e.name]);batchConfirm=false;return;}const row=draft.teeth[selected]||{};if(v===undefined||v===false||v==='')delete row[k];else row[k]=v;if(v===true&&['missing','extracted','extractionPlan'].includes(k))for(const other of ['missing','extracted','extractionPlan'])if(other!==k)delete row[other];syncDetails(row,k,v,false);syncPocket(row,k);el.querySelectorAll('input[type=checkbox]').forEach(e=>e.checked=!!row[e.name]);if(Object.keys(row).length)draft.teeth[selected]=row;else delete draft.teeth[selected];changed();refreshChart();};
