   bindDetail(el,t,set);const detail=el.querySelector('.dn-tooth-detail');detail.open=detailOpen;detail.addEventListener('toggle',()=>detailOpen=detail.open);el.querySelectorAll('[data-pocket],[data-detail],[name=pocketMm],[name=note]').forEach(input=>input.onfocus=()=>{editorFocus=input.dataset.pocket?'[data-pocket="'+input.dataset.pocket+'"]':input.dataset.detail?'[data-detail="'+input.dataset.detail+'"]':'[name="'+input.name+'"]';});if(advance&&editorFocus){const input=el.querySelector(editorFocus);if(input){if(input.closest('.dn-tooth-detail')){detail.open=true;detailOpen=true;}input.focus({preventScroll:true});input.select?.();input.scrollIntoView({block:'nearest'});}}syncEditor();if(!multi)bindEditorImages();paintValidation();
   el.querySelector('[data-clear-tooth]')?.addEventListener('click',()=>{if(!draft.teeth[selected])return;undoSingle={id:selected,before:copy(draft.teeth[selected])};delete draft.teeth[selected];changed();refreshChart();renderEditor();updateUndo();});el.querySelector('[data-batch-apply]')?.addEventListener('click',applyBatch);if(!edit()||conflict)el.querySelectorAll('input,select,textarea,[data-grade],[data-clear-tooth],[data-batch-apply]').forEach(e=>e.disabled=true);
