  function syncPocket(row,k){if(k!=='pockets')return;const vals=Object.values(row.pockets||{});if(vals.length)row.pocketMm=Math.max(...vals);else delete row.pocketMm;}
  function syncEditor(){const el=root.querySelector('[data-editor]');if(!el)return;const t=multi?batch:draft.teeth[selected]||{};el.querySelectorAll('[data-grade]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.value===''?t[e.dataset.grade]==null:t[e.dataset.grade]===Number(e.dataset.value))));for(const e of el.querySelectorAll('[data-detail]'))if(document.activeElement!==e)e.value=t[e.dataset.detail]??'';const max=el.querySelector('[name=pocketMm]');if(max){const derived=Object.keys(t.pockets||{}).length>0;max.readOnly=derived;max.title=derived?'부위별 측정값 중 최댓값':'간편 입력';if(document.activeElement!==max)max.value=t.pocketMm??'';let hint=el.querySelector('[data-pocket-hint]');if(!hint){hint=document.createElement('small');hint.dataset.pocketHint='';max.after(hint);}hint.textContent=derived?'부위별 측정에서 자동 계산':'최댓값만 입력하거나 아래에서 부위별 측정';}}
  function batchRows(){return [...picks].map(id=>{const before=draft.teeth[id]||{},after=copy(before);for(const [k,v] of Object.entries(batch)){if(v===undefined||v===false||v==='')delete after[k];else after[k]=v;if(v===true&&['missing','extracted','extractionPlan'].includes(k))for(const other of ['missing','extracted','extractionPlan'])if(other!==k)delete after[other];}if(Object.hasOwn(batch,'pockets'))syncPocket(after,'pockets');return {id,before,after,overwrites:Object.keys(before).some(k=>!same(before[k],after[k]))};});}
  function applyBatch(){if(!picks.size||!Object.keys(batch).length)return;const rows=batchRows(),over=rows.filter(x=>x.overwrites);if(over.length&&!batchConfirm){root.querySelector('[data-batch-preview]').innerHTML='<p>기존 입력 '+over.length+'개가 변경됩니다.</p>'+over.map(x=>'<p><b>'+x.id+'</b> '+esc(D.toothSummary(x.before))+' → '+esc(D.toothSummary(x.after))+'</p>').join('');root.querySelector('[data-batch-apply]').textContent='위 변경 내용 적용';batchConfirm=true;return;}undoBatch=rows.map(r=>({id:r.id,before:copy(r.before),after:copy(r.after)}));for(const r of rows)if(Object.keys(r.after).length)draft.teeth[r.id]=r.after;else delete draft.teeth[r.id];batch={};batchConfirm=false;changed();refreshChart();renderEditor();updateUndo();}
  function conflictHTML(){if(!conflict)return '';const latest=conflict.latest.body.dentalChart,rows=changes(conflict.base,conflict.local,latest);return '<section class="dn-conflict"><h3>동시 수정 내용 확인</h3><p>겹치지 않는 내 변경은 유지됩니다. 겹친 항목은 반영할 값을 선택하세요.</p><div class="dn-table-wrap"><table><thead><tr><th>항목</th><th>내 입력</th><th>서버 최신 입력</th><th>반영</th></tr></thead><tbody>'+rows.map(c=>'<tr><td>'+esc(label(c.key))+'</td><td>'+esc(value(c.key,c.local))+'</td><td>'+esc(value(c.key,c.remote))+'</td><td>'+(c.conflict?'<select data-conflict="'+esc(c.key)+'"><option value="remote">서버 최신</option><option value="local">내 입력</option></select>':c.mine?'내 입력':'서버 최신')+'</td></tr>').join('')+'</tbody></table></div><button data-resolve class="pt-primary">선택한 내용으로 저장</button><button data-latest>최신 기록 불러오기</button></section>';}
  function bindConflict(){root.querySelector('[data-resolve]').onclick=()=>{const choices={};root.querySelectorAll('[data-conflict]').forEach(e=>choices[e.dataset.conflict]=e.value);draft=merge(conflict.base,conflict.local,conflict.latest.body.dentalChart,choices);item=conflict.latest;baseline=copy(item.body.dentalChart);conflict=null;pending=null;dirty=true;version++;render();void save(false);};root.querySelector('[data-latest]').onclick=()=>{if(!g.confirm('내 미저장 입력을 버리고 서버의 최신 기록을 불러올까요?'))return;item=conflict.latest;draft=copy(item.body.dentalChart);baseline=copy(draft);conflict=null;pending=null;dirty=false;message='최신 기록을 불러왔습니다.';render();};}
  function priorHTML(){return '<section class="dn-prior"><button data-dn="prior" '+(!item.patient_id||priorBusy?'disabled':'')+'>이 환자의 이전 기록'+(priorBusy?' 확인 중…':'')+'</button>'+(!item.patient_id?'<small>등록 환자 연결 시 비교할 수 있습니다.</small>':'')+(prior.length?'<select data-prior-choice aria-label="비교할 이전 기록"><option value="">기록 선택</option>'+prior.filter(r=>r.id!==item.id).map(r=>'<option value="'+esc(r.id)+'">'+esc(r.date)+' · '+esc(r.diagnosis||'소견 미입력')+'</option>').join('')+'</select>':'')+(comparison?'<div class="dn-comparison"><h3>'+esc(comparison.body.dentalChart.date)+' 기록과 비교</h3><label><input data-compare-all type="checkbox" '+(compareAll?'checked':'')+'>변경 없는 항목도 보기</label>'+comparisonCharts()+'<button data-import-review '+(!edit()||conflict?'disabled':'')+'>이전 결손·발치 치아 가져오기</button><div data-import-preview></div><div class="dn-table-wrap"><table><thead><tr><th>항목</th><th>이전</th><th>이번</th></tr></thead><tbody>'+changes({},comparison.body.dentalChart,draft).filter(c=>compareAll||!same(c.local,c.remote)).map(c=>'<tr><td>'+esc(label(c.key))+'</td><td>'+esc(value(c.key,c.local))+'</td><td>'+esc(value(c.key,c.remote))+'</td></tr>').join('')+'</tbody></table></div><button data-dn="compare-close">비교 닫기</button></div>':'')+'</section>';}
  async function history(){if(!item.patient_id)return;const k=token();priorBusy=true;render(true);try{let next='',result=[];do{const p=new URLSearchParams({patientId:item.patient_id});if(next)p.set('cursor',next);const r=await api('/dental?'+p);if(!current(k))return;result.push(...r.items);const old=next;next=r.next||'';if(old&&old===next)throw Error('이전 기록 목록을 다시 확인해주세요.');}while(next);prior=result.sort((a,b)=>b.date.localeCompare(a.date));if(!prior.some(r=>r.id!==item.id))message='이 환자의 이전 치과기록이 없습니다.';}catch(e){if(current(k))message=e.message;}finally{if(current(k)){priorBusy=false;render(true);}}}
  function bindPrior(){root.querySelector('[data-compare-all]')?.addEventListener('change',e=>{compareAll=e.target.checked;render(true);});
   root.querySelector('[data-import-review]')?.addEventListener('click',()=>{if(!edit()||conflict)return;const candidates=importCandidates();root.querySelector('[data-import-preview]').innerHTML=candidates.length?'<p>선택한 치아를 이번 기록의 기존 결손으로 반영합니다. 기존 소견·등급은 복사하지 않습니다.</p>'+candidates.map(id=>'<label><input type="checkbox" data-import-id="'+id+'"> '+id+'번</label>').join('')+'<button data-import-apply>선택 치아 반영</button>':'가져올 새 결손 치아가 없습니다.';root.querySelector('[data-import-apply]')?.addEventListener('click',()=>{const ids=[...root.querySelectorAll('[data-import-id]:checked')].map(e=>e.dataset.importId);if(!ids.length)return;undoBatch=ids.map(id=>({id,before:copy(draft.teeth[id]||{}),after:{...(draft.teeth[id]||{}),missing:true}}));for(const r of undoBatch)draft.teeth[r.id]=copy(r.after);changed();refreshChart();renderEditor();updateUndo();root.querySelector('[data-import-preview]').textContent=ids.length+'개 치아를 기존 결손으로 반영했습니다.';});});root.querySelector('[data-prior-choice]')?.addEventListener('change',async e=>{if(!e.target.value)return;const k=token();try{const r=await api('/cases/'+encodeURIComponent(e.target.value));if(!current(k))return;if(r.item.patient_id!==item.patient_id||r.item.body.category!=='dental'||r.item.body.deleted)throw Error('같은 환자의 치과기록을 선택해주세요.');comparison=r.item;render(true);}catch(e){if(current(k))notice(e.message);}});}
  async function remove(){if(!item.id||busy||!edit())return;if(!g.confirm(item.patient.name+'의 '+draft.date+' 치과기록을 삭제할까요?'))return;clearTimeout(timer);busy=true;updateActions();const k=token();try{await api('/cases/'+item.id+'/events','POST',{requestKey:crypto.randomUUID(),revision:item.revision,kind:'case.delete',data:{confirm:true}});if(!current(k))return;busy=false;dirty=false;reset(true);loaded=false;render();void list();}catch(e){if(current(k)){busy=false;notice('삭제하지 못했습니다. '+e.message);}}}

  function paintPatientSearch(){const out=root.querySelector('[data-search-results]');if(!out)return;out.innerHTML=searchPatients.map(p=>'<button data-pick="'+esc(p.id)+'"><b>'+esc(p.name)+'</b><span>'+esc(p.guardianName||'보호자 미입력')+' · '+({dog:'개',cat:'고양이'}[p.species]||'동물종 확인')+'</span><small>'+esc(p.breed||'품종 미입력')+' · 차트 '+esc(p.chartNumber||p.externalPatientId||'미입력')+'</small></button>').join('')+(patientSearchBusy?'<p>환자 검색 중…</p>':patientSearchError?'<p>'+esc(patientSearchError)+'</p><button data-search-retry>다시 조회</button>':searchPage&&!searchPatients.length?'<p>검색 결과 없음</p>':'')+(searchPage?'<small class="dn-search-count">'+searchPatients.length+'명 표시'+(searchPaging?.total!=null?' / 전체 '+searchPaging.total+'명':'')+'</small>':'')+(searchPaging?.hasNext?'<button data-patient-more '+(patientSearchBusy?'disabled':'')+'>환자 더 보기</button>':'');
   out.querySelector('[data-patient-more]')?.addEventListener('click',()=>void search(true));out.querySelector('[data-search-retry]')?.addEventListener('click',()=>void search(searchPage>0));out.querySelectorAll('[data-pick]').forEach(e=>e.onclick=()=>{if(busy||item.id||pending)return;const p=searchPatients.find(p=>p.id===e.dataset.pick);if(!['dog','cat'].includes(p.species)){notice('환자 등록에서 동물종을 확인해주세요.');return;}picked=p;item.patient=copy(p);item.patient_id=p.id;item.body.species=p.species;draft.weight=p.latestWeightKg??p.weight??null;if(draft.weight==='')draft.weight=null;draft.patient={breed:p.breed||'',birthDate:p.birthDate||p.birth_date||'',sex:p.sex||'unknown',neutered:p.neutered||'unknown'};changed();render();});
  }
  async function search(more=false){const q=root.querySelector('[data-search]')?.value.trim();if(!q)return;if(more&&patientSearchBusy)return;if(q!==searchQuery)more=false;const k=token(),n=++searchSeq;if(!more){searchPatients=[];searchPage=0;searchPaging=null;}searchQuery=q;patientSearchBusy=true;patientSearchError='';paintPatientSearch();try{const r=await a.request('/patient-directory?q='+encodeURIComponent(q)+'&active=active&pageSize=20&page='+(more?searchPage+1:1));if(!current(k)||n!==searchSeq)return;searchPatients=[...new Map([...searchPatients,...(r.patients||[])].map(p=>[p.id,p])).values()];searchPage=r.pagination?.page||(more?searchPage+1:1);searchPaging=r.pagination||null;}catch(e){if(current(k)&&n===searchSeq)patientSearchError='환자 조회 실패 · '+e.message;}finally{if(current(k)&&n===searchSeq){patientSearchBusy=false;paintPatientSearch();}}}

  function action(k){if(k==='new')start();else if(k==='save')void save(false);else if(k==='back'){if(leave(()=>action('back'))){reset(true);loaded=false;render();void list();}}else if(k==='refresh')void list();else if(k==='more')void list(true);else if(k==='search')void search();else if(k==='multi'){multi=!multi;picks.clear();batch={};editorOpen=false;render(true);}else if(k==='batch-open'){editorOpen=true;renderEditor();}else if(k==='staff-retry')void staff();else if(k==='prior')void history();else if(k==='compare-close'){comparison=null;render(true);}else if(k==='delete')void remove();else if(k==='print')openPrintOptions();}

  function syncDetails(row,k,v,batchMode){const remove=key=>{if(batchMode)row[key]=undefined;else delete row[key];};if(k==='mobilityGrade'&&v!==undefined){if(Number(v)>0)row.mobile=true;else remove('mobile');}if(k==='mobile'&&v===false)remove('mobilityGrade');if(['resorptionStage','resorptionType'].includes(k)&&v!==undefined)row.resorption=true;if(k==='resorption'&&v===false){remove('resorptionStage');remove('resorptionType');}}
  function detailHTML(t){const select=(k,label,options)=>'<label>'+label+'<select data-detail="'+k+'"><option value="">미기록</option>'+options.map(v=>'<option '+(String(t[k])===String(v)?'selected':'')+'>'+v+'</option>').join('')+'</select></label>';return '<details class="dn-tooth-detail"><summary>상세 소견</summary><div class="dn-detail-grid">'+select('mobilityGrade','동요도 · M',[0,1,2,3])+select('furcationGrade','분지부 병변 · F',[0,1,2,3])+'<label>치은퇴축 · mm<input data-detail="recessionMm" type="number" min="0" max="50" step="any" value="'+esc(t.recessionMm??'')+'"></label>'+select('resorptionStage','흡수 병변 단계',[1,2,3,'4a','4b','4c',5])+select('resorptionType','흡수 병변 방사선 유형',[1,2,3])+'</div><b>부위별 치주낭 · mm</b><div class="dn-detail-grid">'+Object.entries(D.sites).map(([k,l])=>'<label>'+l+'<input data-pocket="'+k+'" type="number" min="0" max="50" step="any" value="'+esc(t.pockets?.[k]??'')+'"></label>').join('')+'</div><small>부위별 실측값을 기록합니다. 단계·유형은 의료진이 평가합니다.</small></details>';}
  function bindDetail(el,t,set){el.querySelectorAll('[data-detail]').forEach(e=>e.oninput=()=>{const key=e.dataset.detail,v=e.value===''?undefined:key==='resorptionStage'?e.value:Number(e.value);set(key,v);});el.querySelectorAll('[data-pocket]').forEach(e=>e.oninput=()=>{const source=multi?batch:draft.teeth[selected],p={...(source?.pockets||{})};if(e.value==='')delete p[e.dataset.pocket];else p[e.dataset.pocket]=Number(e.value);set('pockets',Object.keys(p).length?p:undefined);syncEditor();});}
  function updateUndo(){const el=root.querySelector('[data-undo]');if(!el)return;el.innerHTML=undoBatch&&edit()?'<button data-undo-batch>방금 일괄 변경 되돌리기</button>':'';el.querySelector('[data-undo-batch]')?.addEventListener('click',()=>{if(conflict||!edit())return;let reverted=0;for(const r of undoBatch||[])if(same(draft.teeth[r.id]||{},r.after)){if(Object.keys(r.before).length)draft.teeth[r.id]=copy(r.before);else delete draft.teeth[r.id];reverted++;}undoBatch=null;changed();refreshChart();renderEditor();updateUndo();notice(reverted+'개 치아를 되돌렸습니다. 저장 중…');});if(undoSingle&&edit()){el.insertAdjacentHTML('beforeend','<button data-undo-single>'+undoSingle.id+'번 지우기 되돌리기</button>');el.querySelector('[data-undo-single]').onclick=()=>{if(conflict||!edit())return;const r=undoSingle;undoSingle=null;if(Object.keys(draft.teeth[r.id]||{}).length){updateUndo();notice('이 치아에 새로 입력한 내용이 있어 덮어쓰지 않았습니다.');return;}draft.teeth[r.id]=copy(r.before);changed();refreshChart();renderEditor();updateUndo();};}}
  function comparisonCharts(){const before=comparison.body.dentalChart.teeth||{},after=draft.teeth;return '<div class="dn-compare-charts">'+[[before,'이전'],[after,'이번']].map(([data,title])=>'<section><b>'+title+'</b><div class="dn-compare-teeth">'+D.teeth(item.body.species).filter(id=>compareAll||!same(before[id],after[id])).map(id=>'<span class="dn-state-'+D.toothState(data[id])+' '+(!same(before[id],after[id])?'dn-changed':'')+'" title="'+esc(D.toothSummary(data[id]))+'">'+id+'<small>'+esc(D.treatment(data[id])||D.states[D.toothState(data[id])])+'</small></span>').join('')+'</div></section>').join('')+'</div>';}
  function importCandidates(){if(!comparison||comparison.patient_id!==item.patient_id||comparison.body.species!==item.body.species)return [];return D.teeth(item.body.species).filter(id=>{const t=comparison.body.dentalChart.teeth[id],now=draft.teeth[id];return (t?.missing||t?.extracted)&&!now;});}
  function cacheImages(images){for(const im of images||[])if(im.dataUrl)imageCache.set(im.id,im.dataUrl);}
  function stripImageData(chart){for(const im of chart.images||[])if(im.imageRevision)delete im.dataUrl;}
  async function imageData(im){if(im.dataUrl)return im.dataUrl;if(imageCache.has(im.id))return imageCache.get(im.id);const k=token(),r=await api('/cases/'+item.id+'/dental-images?id='+encodeURIComponent(im.id));if(!current(k))throw Error('다른 기록으로 이동했습니다.');imageCache.set(im.id,r.dataUrl);return r.dataUrl;}
  function loadThumbnails(){const k=token();for(const im of (draft.images||[]).filter(im=>root.querySelector('.dn-related')?.open||editorOpen&&im.toothId===selected))void imageData(im).then(src=>{if(!current(k))return;root.querySelectorAll('[data-image-thumb="'+CSS.escape(im.id)+'"]').forEach(el=>{el.src=src;el.hidden=false;});root.querySelectorAll('[data-image-loading="'+CSS.escape(im.id)+'"]').forEach(msg=>msg.hidden=true);}).catch(()=>{if(!current(k))return;const msg=root.querySelector('[data-image-loading="'+CSS.escape(im.id)+'"]');if(msg)msg.textContent='이미지 열기로 다시 시도';});}
  async function printSaved(){if(busy||conflict||!canSave())return;const k=token(),win=g.open('','_blank');if(!win){notice('인쇄 창의 팝업을 허용해주세요.');return;}win.opener=null;win.document.body.textContent='저장 후 인쇄 기록을 준비하고 있습니다…';if((dirty||!item.id)&&!await save(false)){win.close();return;}if(!current(k)||dirty){win.close();return;}try{const printed=copy(draft);if(printImages)printed.images=await Promise.all((printed.images||[]).map(async im=>({...im,dataUrl:await imageData(im)})));else printed.images=[];if(!current(k)){win.close();return;}win.document.open();win.document.write(D.printHtml(item,printed,a.clinicName?.()||'',{mode:printMode,images:printImages}));win.document.close();}catch(e){win.close();if(current(k))notice('인쇄 준비 실패 · '+e.message);}}
  function extrasHTML(){return '<details class="dn-related"><summary>마취기록·이미지·보호자 안내</summary><div class="dn-related-tools"><button data-related-load '+(!item.patient_id||relatedBusy?'disabled':'')+'>같은 환자 마취기록'+(relatedBusy?' 조회 중…':'')+'</button>'+(edit()?'<button data-guide-create>보호자 안내 초안 만들기</button>':'')+'</div><div data-related-list>'+relatedHTML()+'</div>'+(!item.patient_id?'<small>등록 환자 연결 시 마취기록을 찾을 수 있습니다.</small>':'')+'<section><h3>치아 연결 이미지</h3><small data-image-limit></small>'+(edit()?'<div class="dn-image-input"><label>치아<select data-image-tooth><option value="">전체 구강</option>'+D.teeth(item.body.species).map(id=>'<option '+(id===selected?'selected':'')+'>'+id+'</option>').join('')+'</select></label><label>종류<select data-image-kind><option value="oral">구강 사진</option><option value="radiograph">방사선 이미지</option></select></label><label>설명<input data-image-caption maxlength="160"></label><label>이미지 추가<input data-image-file type="file" accept="image/jpeg,image/png,image/webp" '+(imageBusy?'disabled':'')+'></label></div><small>기록용 미리보기 · 최대 4장. 저장 시 축소되며 판독용 원본은 별도로 보관하세요.</small>':'')+'<div data-image-list>'+imagesHTML()+'</div></section><div data-guide>'+guideHTML()+'</div></details>';}
